// SPDX-License-Identifier: Apache-2.0
// `m3Plugin`: the one Bun plugin of an @aphrody/m3 application. It composes
//   - Tailwind v4 for CSS roots (`@aphrody/bun-plugin-tailwind`),
//   - `.scss` through Rust (`sassRustPlugin` from `@aphrody/bun`, loaded on first use),
//   - the `m3:*` virtual modules: theme sheets generated by `crates/ui/m3-tokens` and the
//     fonts shipped by `crates/ui/bun/icons` and `crates/ui/m3-tokens/fonts`,
//   - Vite-style `?url` imports.
//
// Programmatic use: `Bun.build({ plugins: [m3Plugin({ theme })] })`.
// Dev server: `bunfig.toml` -> `[serve.static] plugins = ["@aphrody/m3/plugin"]` loads the default
// export, which reads the theme from the `m3.config.ts` of the working directory.
import type { BunPlugin, OnLoadResult, PluginBuilder } from "bun";
import { faceRule, fontFace } from "@aphrody/m3-fonts";
import { existsSync } from "node:fs";
import { basename, dirname, join, resolve } from "node:path";
import { findM3Config, loadM3Config, type M3ThemeConfig } from "./config";
import {
  cssRequest,
  defaultM3Css,
  findNativeTheme,
  loadAphrodyBun,
  nativeThemeMatches,
  readNativeTheme,
  type M3CssFn,
  type M3Sheet,
} from "./native";
import { fontPaths, resolveRepoRoot, SYMBOL_STYLES, type SymbolStyle } from "./paths";
import { setupUrlImports } from "./url-imports";
import { compileSheet, tailwindM3Plugin } from "./tailwind";

export type { M3CssConfig, M3CssFn, M3Sheet } from "./native";

/** Namespace of the generated `m3:*` sheets. */
export const M3_NAMESPACE = "m3";

/** `m3:<name>.css` -> sheet generated by `m3Css`. `m3:theme.css` is the token sheet. */
export const SHEET_MODULES: Readonly<Record<string, M3Sheet>> = {
  "theme.css": "tokens",
  "tokens.css": "tokens",
  "tailwind.css": "tailwind",
  "spaceui.css": "spaceui",
  "scheme.css": "scheme",
};

/** `m3:<name>.css` -> Material Symbols style (real CSS files next to the woff2 in `crates/ui/bun/icons`). */
export const SYMBOL_MODULES: Readonly<Record<string, SymbolStyle>> = {
  "symbols.css": "outlined",
  "symbols-outlined.css": "outlined",
  "symbols-rounded.css": "rounded",
  "symbols-sharp.css": "sharp",
};

/** `m3:fonts.css`: Google Sans Flex. Its file name lives in the font directory so `url()` resolves. */
export const FONTS_MODULE = "fonts.css";
const FONTS_VIRTUAL = "__m3-fonts.css";

/** Every `m3:*` specifier the plugin serves. */
export const M3_MODULES: readonly string[] = [
  ...Object.keys(SHEET_MODULES),
  ...Object.keys(SYMBOL_MODULES),
  FONTS_MODULE,
].map((name) => `m3:${name}`);

export interface M3PluginOptions {
  /** Inputs of the generated sheets. Default: `theme` of the `m3.config.ts` in `configDir`. */
  theme?: M3ThemeConfig;
  /** Directory searched for `m3.config.*` when `theme` is not given (default: working directory). */
  configDir?: string;
  /** Sheet generator. Default: `m3Css` from `@aphrody/bun`, loaded on first use. */
  css?: M3CssFn;
  /** Paired native ThemeExport JSON/CSS. Default: the selected workspace's design-sync corpus.
   * Explicit artifacts must match the token request; automatic mismatches use the native generator. */
  nativeTheme?: string;
  /** Aphrody OS checkout holding the fonts (default: discovered). */
  root?: string;
  /** Compose the separately resolved Tailwind engine and Oxide scanner (default true). When false,
   * the `m3:*` sheets are lowered to plain CSS by {@link lowerThemeRules}. */
  tailwind?: boolean;
  /** Compile `.scss` through `@aphrody/bun` (default true), or pass its options. */
  sass?: boolean | { loadPaths?: string[]; style?: "expanded" | "compressed"; quiet?: boolean };
  /** `?url` imports (default true): `.svg` as file assets, other assets inlined as data URLs. */
  urlImports?: boolean;
}

/** `@font-face` for Google Sans Flex (declared by `@aphrody/m3-fonts`), relative to the font directory. */
export function fontsCss(): string {
  // The manifest face points at the Latin WOFF2 subset; this sheet serves the full TrueType source.
  const { unicodeRange: _subset, ...face } = fontFace("Google Sans Flex");
  return `${faceRule({ ...face, format: "truetype" }, "./GoogleSansFlex-Variable.ttf")}\n`;
}

/** Index just past the comment or string starting at `i`, or `i` when neither starts there. */
function skipOpaque(css: string, i: number): number {
  if (css.startsWith("/*", i)) {
    const end = css.indexOf("*/", i + 2);
    if (end < 0) throw new Error("@aphrody/m3: unterminated comment in an m3 sheet");
    return end + 2;
  }
  const quote = css[i];
  if (quote !== '"' && quote !== "'") return i;
  for (let j = i + 1; j < css.length; j++) {
    if (css[j] === "\\") j++;
    else if (css[j] === quote) return j + 1;
  }
  throw new Error("@aphrody/m3: unterminated string in an m3 sheet");
}

/** Index of the `}` closing the block whose `{` is at `open`. */
function blockEnd(css: string, open: number): number {
  let depth = 0;
  for (let i = open; i < css.length;) {
    const next = skipOpaque(css, i);
    if (next !== i) {
      i = next;
      continue;
    }
    if (css[i] === "{") depth++;
    else if (css[i] === "}" && --depth === 0) return i;
    i++;
  }
  throw new Error("@aphrody/m3: unbalanced braces in an m3 sheet");
}

/**
 * Plain CSS for a sheet compiled without Tailwind: `@theme inline` and `@theme reference` only feed
 * Tailwind utilities and are dropped; any other `@theme` block declares real variables and becomes
 * `:root, :host`, as Tailwind emits it. Nested at-rules (`@keyframes`) are hoisted after the rule and
 * namespace resets (`--color-*: initial`) are removed.
 */
export function lowerThemeRules(css: string): string {
  let out = "";
  let from = 0;
  for (let i = 0; i < css.length;) {
    const next = skipOpaque(css, i);
    if (next !== i) {
      i = next;
      continue;
    }
    if (!/^@theme(?![\w-])/.test(css.slice(i, i + 7))) {
      i++;
      continue;
    }
    const open = css.indexOf("{", i);
    if (open < 0) throw new Error("@aphrody/m3: @theme without a block in an m3 sheet");
    const params = new Set(
      css
        .slice(i + "@theme".length, open)
        .trim()
        .split(/\s+/),
    );
    const close = blockEnd(css, open);
    out += css.slice(from, i);
    if (!params.has("inline") && !params.has("reference")) {
      const body = css.slice(open + 1, close);
      let declarations = "";
      let hoisted = "";
      let start = 0;
      for (let j = 0; j < body.length;) {
        const skipped = skipOpaque(body, j);
        if (skipped !== j) {
          j = skipped;
          continue;
        }
        if (body[j] === "@") {
          const nestedOpen = body.indexOf("{", j);
          const nestedClose = blockEnd(body, nestedOpen);
          declarations += body.slice(start, j);
          hoisted += `\n${body.slice(j, nestedClose + 1)}`;
          j = start = nestedClose + 1;
          continue;
        }
        j++;
      }
      declarations += body.slice(start);
      declarations = declarations.replace(/^[ \t]*--[\w-]*\*[\w-]*\s*:[^;]*;[ \t]*\r?\n?/gm, "");
      out += `:root, :host {${declarations}}${hoisted}`;
    }
    i = from = close + 1;
  }
  return out + css.slice(from);
}

type LoadCallback = (args: {
  path: string;
  namespace: string;
}) => OnLoadResult | Promise<OnLoadResult>;

/** Build the plugin. */
export function m3Plugin(options: M3PluginOptions = {}): BunPlugin {
  let generator: Promise<M3CssFn> | undefined;
  let theme: Promise<M3ThemeConfig> | undefined;
  const sheets = new Map<string, Promise<string>>();
  let artifact: ReturnType<typeof readNativeTheme> | null | undefined;

  const getArtifact = () => {
    if (artifact !== undefined) return artifact;
    const path = options.nativeTheme ?? findNativeTheme(options.configDir ?? process.cwd());
    return (artifact = path ? readNativeTheme(path) : null);
  };

  const getGenerator = () =>
    (generator ??= options.css ? Promise.resolve(options.css) : defaultM3Css());
  const getTheme = () =>
    (theme ??= (async () => {
      if (options.theme) return options.theme;
      const dir = options.configDir ?? process.cwd();
      return findM3Config(dir) ? ((await loadM3Config(dir)).theme ?? {}) : {};
    })());
  const sheet = (kind: M3Sheet) => {
    let css = sheets.get(kind);
    if (!css) {
      css = (async () => {
        const request = cssRequest(kind, await getTheme());
        if (!options.css && kind === "tokens") {
          const exported = getArtifact();
          if (exported && nativeThemeMatches(request, exported.theme)) return exported.css;
          if (options.nativeTheme)
            throw new Error(
              "@aphrody/m3: native theme artifact does not match the requested seed, variant or contrast",
            );
        }
        return (await getGenerator())(request);
      })();
      sheets.set(kind, css);
    }
    return css;
  };

  return {
    name: "@aphrody/m3",
    setup(build: PluginBuilder) {
      // The m3 hooks come first: the Tailwind loader would otherwise try to read the virtual
      // font sheet from disk.
      build.onResolve({ filter: /^m3:/ }, (args) => {
        const name = args.path.slice("m3:".length);
        if (name in SHEET_MODULES) return { path: name, namespace: M3_NAMESPACE };
        const fonts = fontPaths(resolveRepoRoot(options.root));
        const style = SYMBOL_MODULES[name];
        if (style) return { path: join(fonts.symbolsDir, `${style}.css`) };
        if (name === FONTS_MODULE) return { path: join(fonts.sansFlexDir, FONTS_VIRTUAL) };
        throw new Error(
          `@aphrody/m3: unknown module ${args.path} (known: ${M3_MODULES.join(", ")})`,
        );
      });
      build.onResolve({ filter: /\.(woff2?|ttf|otf|eot)$/ }, (args) => {
        if (args.importer) {
          const directTarget = resolve(dirname(args.importer), args.path);
          if (existsSync(directTarget)) return { path: directTarget };
        }
        if (args.path.includes("fonts/web/")) {
          try {
            const fontTarget = Bun.resolveSync(
              `@aphrody/m3-fonts/fonts/web/${basename(args.path)}`,
              args.importer ? dirname(args.importer) : process.cwd(),
            );
            if (existsSync(fontTarget)) return { path: fontTarget };
          } catch {}
        }
        return undefined;
      });
      build.onLoad({ filter: /.*/, namespace: M3_NAMESPACE }, async (args) => {
        const kind = SHEET_MODULES[args.path];
        if (!kind) throw new Error(`@aphrody/m3: unknown sheet m3:${args.path}`);
        const css = await sheet(kind);
        if (options.tailwind === false) return { contents: lowerThemeRules(css), loader: "css" };
        const base = options.configDir ?? process.cwd();
        return { contents: await compileSheet(`m3-${args.path}`, css, base), loader: "css" };
      });
      build.onLoad({ filter: /__m3-fonts\.css$/ }, () => ({ contents: fontsCss(), loader: "css" }));

      if (options.urlImports !== false) setupUrlImports(build);

      if (options.sass !== false) {
        const sassOptions = typeof options.sass === "object" ? options.sass : {};
        let compile: Promise<LoadCallback> | undefined;
        build.onLoad({ filter: /\.scss$/ }, async (args) => {
          compile ??= (async () => {
            const { sassRustPlugin } = await loadAphrodyBun();
            if (typeof sassRustPlugin !== "function")
              throw new Error("@aphrody/m3: @aphrody/bun has no sassRustPlugin");
            let captured: LoadCallback | undefined;
            sassRustPlugin(sassOptions).setup({
              onLoad(_filter: unknown, callback: LoadCallback) {
                captured = callback;
              },
            });
            if (!captured) throw new Error("@aphrody/m3: sassRustPlugin registered no loader");
            return captured;
          })();
          return (await compile)(args);
        });
      }

      // The token sheets carry `@theme inline`: Tailwind compiles them with the root that imports them.
      if (options.tailwind !== false)
        void tailwindM3Plugin({
          schemeImport: (id) => {
            const name = id.slice("m3:".length);
            return id.startsWith("m3:") && Object.hasOwn(SHEET_MODULES, name)
              ? sheet(SHEET_MODULES[name])
              : undefined;
          },
        }).setup(build);
    },
  };
}

/** The plugin with its defaults, for `bunfig.toml` `[serve.static] plugins = ["@aphrody/m3/plugin"]`. */
const plugin: BunPlugin = m3Plugin();
export default plugin;

/** Styles of Material Symbols shipped as `m3:symbols-<style>.css`. */
export { SYMBOL_STYLES };
